$packageIds = $classes->getCollection()
    ->pluck('PackageID')->filter(fn ($id) => $id > 0)->unique()->values()->all();
$packageMap = !empty($packageIds)
    ? CoursePackage::whereIn('id', $packageIds)->get()->keyBy('id')
    : collect();

// FR-001: Compute package remaining sessions from actual attendance (not ledger snapshot).
// PackageSessionLedger may be stale if courses were assigned to a package after sessions
// were already attended, or if early attendance paths did not trigger PackageDeductionService.
// We load ALL member classes (not just those on the current page) to ensure the aggregate
// is complete regardless of pagination — CQRS: view-layer pagination must not truncate aggregates.
if (!empty($packageIds)) {
    $membersByPkg = StudentClass::whereIn('PackageID', $packageIds)
        ->select('PackageID', 'ID')
        ->get()
        ->groupBy('PackageID');
    $allMemberIds = $membersByPkg->flatten()->pluck('ID')->unique()->values()->all();
    $allMemberIds = array_values(array_filter(array_map('intval', $allMemberIds), fn ($id) => $id > 0));
    $observedUsedByMember = !empty($allMemberIds)
        ? SessionDeductionService::batchObservedUsedSessions($allMemberIds)
        : [];
    foreach ($packageMap as $pkgId => $pkg) {
        $members = $membersByPkg->get($pkgId, collect());
        $totalUsed = $members->sum(fn ($m) => $observedUsedByMember[(int) $m->ID] ?? 0);
        $pkg->used_sessions      = $totalUsed;
        $pkg->remaining_sessions = max(0, (int) $pkg->total_sessions - $totalUsed);
    }
}

