$oldStartTimeProvided = $oldStartTime !== null && $oldStartTime !== '';
$oldStartTimeNormalized = $oldStartTimeProvided ? $this->normalizeProjectionTime($oldStartTime) : null;
if ($oldDate) {
    $query = ClassSession::where('StudentClassID', $classId)
        ->where('SessionDate', $oldDate);
    if ($oldStartTimeProvided) {
        if ($oldStartTimeNormalized) {
            $session = (clone $query)->where('StartTime', $oldStartTimeNormalized)->first();
        }
        if (!$session) {
            return response()->json([
                'message' => '找不到指定堂次，請確認日期與時間是否正確',
                'student_class_id' => $classId,
                'old_date' => $oldDate,
                'old_start_time' => $oldStartTime,
            ], 422);
        }
    } else {
        // Backward compatibility: callers that have not yet been updated to pass
        // old_start_time continue to use the first-by-date behavior.
        $session = $query->first();
    }
}

if ($session) {
    $oldStatus = strtolower(trim((string) ($session->Status ?? 'scheduled')));
    $originalSessionDate = $this->normalizeDateValue($session->SessionDate);
    $originalStartTime = $this->normalizeProjectionTime($session->StartTime);

    try {
        $resetApplied = DB::transaction(function () use (
            $session, $studentClass, $authUserId, $oldStatus,
            $newDate, $startTime, $endTime,
            $originalSessionDate, $originalStartTime, $classId
        ) {
            $session->SessionDate = $newDate;
            if ($startTime) $session->StartTime = $startTime;
            if ($endTime)   $session->EndTime   = $endTime;
            $session->save();

            $resetApplied = false;
            if ($this->shouldResetToScheduledByReschedule($session)) {
                $resetApplied = $this->resetRescheduledFutureSession($session, $studentClass, $authUserId, $oldStatus);
            }

            LearningRecord::where('ClassSessionID', $session->id)->update([
                'SessionDate' => $session->SessionDate,
                'StartTime' => $session->StartTime,
                'EndTime' => $session->EndTime,
            ]);

            // FR-004: keep schedules substitute rows aligned with the new ClassSession
            // time so ClassSessionController::index JOIN (which matches on
            // DATE(schedule_date) = DATE(cs.SessionDate) AND sub_sched.start_time =
