            // after a reschedule. Scope is restricted to the substitute rows
            // (original_schedule_id IS NOT NULL) plus their matching rescheduled
            // anchor row so the pair remains consistent.
            $this->syncSchedulesForRescheduledSession(
                $classId,
                $originalSessionDate,
                $originalStartTime,
                $session
            );

            return $resetApplied;
        });
    } catch (\Throwable $e) {
        Log::error('reschedule_session_failed', [
            'session_id' => $session->id,
            'student_class_id' => $classId,
            'error' => $e->getMessage(),
