use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\Facades\Schema;
use Carbon\Carbon;

/**
 * FR-004 helper: when a ClassSession is moved to a new date/time by a reschedule,
 * keep the paired substitute rows in the `schedules` table aligned so
 * ClassSessionController::index JOIN continues to resolve the substitute teacher.
 *
 * Only rows whose anchor row is the `rescheduled` row for the original date/time
 * (or the substitute rows that point to that anchor) are touched. This narrow scope
 * avoids any risk of touching unrelated schedules on other dates.
 */
private function syncSchedulesForRescheduledSession(
    int $classId,
    ?string $originalSessionDate,
    ?string $originalStartTime,
    ClassSession $session
): void {
    if (!$originalSessionDate) {
        return;
    }

    $newStartTimeShort = $this->normalizeProjectionTime($session->StartTime);
    $newEndTimeShort = $this->normalizeProjectionTime($session->EndTime);
    $newStartHm = $newStartTimeShort ? substr($newStartTimeShort, 0, 5) : null;
    $newEndHm = $newEndTimeShort ? substr($newEndTimeShort, 0, 5) : null;
    $newDateOnly = $this->normalizeDateValue($session->SessionDate);
    $originalStartHm = $originalStartTime ? substr($originalStartTime, 0, 5) : null;

    // 1) Locate the anchor "rescheduled" row from the original (date, start_time).
    //    The substitute upsert at ClassSessionController::substitute creates it keyed
    //    by (student_course_id, schedule_date, status=rescheduled) but in practice
    //    start_time also matches the original ClassSession.StartTime.
    $rescheduledAnchors = Schedule::where('student_course_id', $classId)
        ->whereDate('schedule_date', $originalSessionDate)
        ->where('status', 'rescheduled');
    if ($originalStartHm) {
        $rescheduledAnchors = $rescheduledAnchors->where('start_time', $originalStartHm);
    }
    $anchorIds = $rescheduledAnchors->pluck('id')->all();

    // 2) Find substitute (scheduled + original_schedule_id IN anchors) rows.
    $substituteQuery = Schedule::where('student_course_id', $classId)
        ->whereDate('schedule_date', $originalSessionDate)
        ->where('status', 'scheduled')
        ->whereNotNull('original_schedule_id');
    if (!empty($anchorIds)) {
        $substituteQuery->whereIn('original_schedule_id', $anchorIds);
    } elseif ($originalStartHm) {
        // Fallback: still restrict by original start_time to avoid accidentally
        // touching unrelated substitute rows on the same day.
        $substituteQuery->where('start_time', $originalStartHm);
    }
    $substituteIds = $substituteQuery->pluck('id')->all();

    if (empty($anchorIds) && empty($substituteIds)) {
        return; // no substitute pair to sync; nothing to do.
    }

    $updates = [];
    if ($newDateOnly) {
        $updates['schedule_date'] = $newDateOnly;
    }
    if ($newStartHm) {
        $updates['start_time'] = $newStartHm;
    }
    if ($newEndHm) {
        $updates['end_time'] = $newEndHm;
    }

    if (empty($updates)) {
        return;
    }

    $targetIds = array_values(array_unique(array_merge($anchorIds, $substituteIds)));
    Schedule::whereIn('id', $targetIds)->update($updates);

    Log::info('reschedule_session.schedules_synced', [
        'student_class_id' => $classId,
        'original_date' => $originalSessionDate,
        'original_start_time' => $originalStartHm,
        'new_date' => $newDateOnly,
        'new_start_time' => $newStartHm,
        'anchor_ids' => $anchorIds,
        'substitute_ids' => $substituteIds,
    ]);
}

